INSERT INTO note_templates (sort_no, body) VALUES (1, '工事用電力、水道、資材置場、足場設置および駐車スペースの無償提供をお願い致します。');
INSERT INTO note_templates (sort_no, body) VALUES (2, '資材搬入は御社休日を設定する等、打合せさせていただきます。');
INSERT INTO note_templates (sort_no, body) VALUES (3, '数量は実寸法から多少違いが生じることがございます。見積書項目以外の工事は、別途相談とさせていただきます。');
INSERT INTO note_templates (sort_no, body) VALUES (4, '工事の際にほこりや塵・切粉が舞うことが想定されますのでご協力ください。');
INSERT INTO note_templates (sort_no, body) VALUES (5, '建物周辺の物や車の移動のご協力をお願いする場合があります。');
INSERT INTO note_templates (sort_no, body) VALUES (6, '本工事で発生した切粉や塵・ほこりによって製品及び機械へ不具合を与えた場合の責任は負いかねます。');
INSERT INTO note_templates (sort_no, body) VALUES (7, '改修工事の為、施工中に雨漏りが発生する場合がありますのでご了承下さい。');
INSERT INTO note_templates (sort_no, body) VALUES (8, '電気工事、配線防護管養生費、配線の撤去は別途工事といたします。');
INSERT INTO note_templates (sort_no, body) VALUES (9, '屋根、外壁に傷がついた場合は、タッチアップを基本といします。');
INSERT INTO note_templates (sort_no, body) VALUES (10, '屋根、外壁の不陸や鉄骨の状況によって新しい屋根がへこむ可能性があります。');
INSERT INTO note_templates (sort_no, body) VALUES (11, '鉄板端部は初期錆が発生する可能性がありますが、ガルバリウムの犠牲防食作用が働き進行を遅らせるものとしています。');
INSERT INTO note_templates (sort_no, body) VALUES (12, 'ビスの打ち間違えが発生する場合があります。その際の補修はコーキングまたは、ビスで塞ぐものとします。');
INSERT INTO note_templates (sort_no, body) VALUES (13, 'ただし明らかに雨漏りに繋がるダメ穴の場合は適正な処置をさせていただきます。また判断に迷った場合は御社にご相談の上、対応させて頂きます。');
INSERT INTO note_templates (sort_no, body) VALUES (14, '明り取りは塞ぐ仕様としています。');
INSERT INTO note_templates (sort_no, body) VALUES (15, '白ガス管設置は工事範囲外としています。');
INSERT INTO note_templates (sort_no, body) VALUES (16, 'ラジアル加工をなくし軒先ストレートで雨樋を設置する仕様としています。');
INSERT INTO note_templates (sort_no, body) VALUES (17, '壁つなぎは既存フックボルトを使用いたします。');
INSERT INTO note_templates (sort_no, body) VALUES (18, '下屋や庇、谷樋は工事範囲外としています。');
INSERT INTO note_templates (sort_no, body) VALUES (19, '既存スレート屋根の清掃や洗浄作業はアスベスト飛散の観点から実施することができません。');
INSERT INTO note_templates (sort_no, body) VALUES (20, '警備員等が必要な場合は別途費用が発生します。');
INSERT INTO note_templates (sort_no, body) VALUES (21, 'トップコートはグレー、ライトグレー、ブルー以外は追加費用が発生します。');
INSERT INTO note_templates (sort_no, body) VALUES (22, '蘇生工法は見た目が悪くなる場合があります。');
INSERT INTO note_templates (sort_no, body) VALUES (23, 'プライマーは溶剤のため臭いが気になる可能性があります。');
INSERT INTO note_templates (sort_no, body) VALUES (24, '既存の塗料によってはケレンが必要となり、別途費用が発生することがあります。');
INSERT INTO note_templates (sort_no, body) VALUES (25, '弱酸が蘇生工法に不具合をきたす場合があるため、換気扇の板金をステンレス鋼鈑しています。');
INSERT INTO note_templates (sort_no, body) VALUES (26, '埋設管との接続は、、、');
INSERT INTO note_templates (sort_no, body) VALUES (27, '竪樋は解放としています。');
