INSERT INTO project_notes (project_id, sort_no, body) SELECT @pid, 14, '明り取りは塞ぐ仕様としています。' FROM DUAL WHERE NOT @skip;
INSERT INTO project_notes (project_id, sort_no, body) SELECT @pid, 15, '白ガス管設置は工事範囲外としています。' FROM DUAL WHERE NOT @skip;
