INSERT INTO project_notes (project_id, sort_no, body) SELECT @pid, 18, '下屋や庇、谷樋は工事範囲外としています。' FROM DUAL WHERE NOT @skip;
INSERT INTO project_notes (project_id, sort_no, body) SELECT @pid, 19, '既存スレート屋根の清掃や洗浄作業はアスベスト飛散の観点から実施することができません。' FROM DUAL WHERE NOT @skip;
INSERT INTO project_notes (project_id, sort_no, body) SELECT @pid, 20, '警備員等が必要な場合は別途費用が発生します。' FROM DUAL WHERE NOT @skip;
INSERT INTO project_notes (project_id, sort_no, body) SELECT @pid, 21, 'トップコートはグレー、ライトグレー、ブルー以外は追加費用が発生します。' FROM DUAL WHERE NOT @skip;
INSERT INTO project_notes (project_id, sort_no, body) SELECT @pid, 22, '蘇生工法は見た目が悪くなる場合があります。' FROM DUAL WHERE NOT @skip;
INSERT INTO project_notes (project_id, sort_no, body) SELECT @pid, 23, 'プライマーは溶剤のため臭いが気になる可能性があります。' FROM DUAL WHERE NOT @skip;
INSERT INTO project_notes (project_id, sort_no, body) SELECT @pid, 24, '既存の塗料によってはケレンが必要となり、別途費用が発生することがあります。' FROM DUAL WHERE NOT @skip;
INSERT INTO project_notes (project_id, sort_no, body) SELECT @pid, 25, '弱酸が蘇生工法に不具合をきたす場合があるため、換気扇の板金をステンレス鋼鈑しています。' FROM DUAL WHERE NOT @skip;
